(function(){'use strict';
var DATA={"name": "Walking Cities", "steps": ["tread districts subsystem nominal", "crawler transit flow stable", "route planning cycle complete", "walker hulls output verified", "mobile blocks levels in range", "plains link steady"], "seed": 98914};
function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
